import boto3


def stream_platform_generation(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))
    response = client.converse(
        modelId="us.amazon.nova-pro-v1:0",
        messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
        stream=True,
    )
    for event in response["output"]:
        if "message" in event:
            yield event["message"]
        else:
            yield event

import boto3


def collect_platform_metadata(payload, config=None):
    config = config or {}
    client = boto3.client("bedrock-runtime", region_name=config.get("region", "us-east-1"))
    response = client.converse(
        modelId="us.amazon.nova-pro-v1:0",
        messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
    )
    metadata = {
        "usage": response["usage"],
        "resourceId": response["responseMetadata"]["requestId"],
        "modelHandle": response["modelId"],
    }
    return metadata

import boto3


class ModelClient:
    def __init__(self, config=None):
        self.config = config or {}
        self.client = boto3.client("bedrock-runtime", region_name=self.config.get("region", "us-east-1"))

    def invoke_model(self, payload):
        response = self.client.converse(
            modelId="us.amazon.nova-pro-v1:0",
            messages=[{"role": "user", "content": [{"text": payload["text"]}]}],
        )
        text = "".join(block["text"] for block in response["output"]["message"]["content"] if "text" in block)
        return {"text": text}

from typing import Dict, List


class ModelRequest:
    def __init__(self, text: str):
        self.text = text


class ModelResponse:
    def __init__(self, text: str):
        self.text = text


def normalize_response(response: Dict) -> ModelResponse:
    text = "".join(block["text"] for block in response["output"]["message"]["content"] if "text" in block)
    return ModelResponse(text)
